(()=>{
const doc=document.querySelector('.document');if(!doc)return;
const bar=document.querySelector('#reading-progress'),pct=document.querySelector('#reading-percent'),chapters=[...document.querySelectorAll('.chapter')],nav=[...document.querySelectorAll('.sidebar nav a')];let queued=false;
const update=()=>{const start=doc.getBoundingClientRect().top+scrollY,end=start+doc.offsetHeight-innerHeight;const value=Math.max(0,Math.min(100,(scrollY-start)/Math.max(1,end-start)*100));bar.style.width=value+'%';if(pct)pct.textContent=Math.round(value)+' %';let active='';for(const c of chapters)if(c.getBoundingClientRect().top<200)active=c.id;nav.forEach(a=>{a.classList.toggle('active',a.dataset.chapter===active);if(a.dataset.chapter===active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});queued=false};
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);addEventListener('load',update);update();
const popup=document.querySelector('#definition');let owner=null;
const hide=()=>{if(owner){owner.setAttribute('aria-expanded','false');owner.removeAttribute('aria-describedby')}owner=null;popup.hidden=true};
const show=t=>{hide();owner=t;popup.textContent=t.dataset.definition;popup.hidden=false;t.setAttribute('aria-expanded','true');t.setAttribute('aria-describedby','definition');const b=t.getBoundingClientRect(),p=popup.getBoundingClientRect();popup.style.left=Math.max(12,Math.min(b.left,innerWidth-p.width-12))+'px';popup.style.top=(b.bottom+p.height+16<innerHeight?b.bottom+8:Math.max(8,b.top-p.height-8))+'px'};
document.querySelectorAll('.term').forEach(t=>{t.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')show(t)});t.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&document.activeElement!==t)hide()});t.addEventListener('focus',()=>show(t));t.addEventListener('blur',hide);t.addEventListener('click',()=>show(t))});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.term'))hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});addEventListener('scroll',hide,{passive:true});
document.querySelectorAll('.mobile-toc a').forEach(a=>a.addEventListener('click',()=>a.closest('details').removeAttribute('open')));
let size=22;try{size=Number(localStorage.getItem('readingSize'))||22}catch{}size=Math.max(18,Math.min(28,size));const setSize=()=>{doc.style.setProperty('--reading-size',size+'px');try{localStorage.setItem('readingSize',size)}catch{}update()};setSize();document.querySelector('#type-smaller').onclick=()=>{size=Math.max(18,size-1);setSize()};document.querySelector('#type-larger').onclick=()=>{size=Math.min(28,size+1);setSize()};
let toastTimer;document.querySelectorAll('.copy-link').forEach(b=>b.addEventListener('click',async()=>{const url='https://libererlembauche.com/code#'+b.dataset.anchor;try{await navigator.clipboard.writeText(url);const toast=document.querySelector('#toast');toast.textContent='Lien de l’article copié';toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),1800)}catch{location.hash=b.dataset.anchor}}));
})();
